function smLogoClass(_c: SmConnector): string {
  // All connectors use real PNG logos now (Figma 127:129366) — no chip fallbacks.
  return 'sm-logo';
}
// Uniquify SVG IDs so the same logo SVG can appear in both Explore and Connected
// panels without `<defs>` collisions blanking subsequent copies.
function smUniquifySvgIds(svg: string, suffix: string): string {
  if (!svg.includes('<svg')) return svg;
  return svg
    .replace(/id="([^"]+)"/g, 'id="$1_' + suffix + '"')
    .replace(/href="#([^"]+)"/g, 'href="#$1_' + suffix + '"')
    .replace(/url\(#([^)]+)\)/g, 'url(#$1_' + suffix + ')');
}
function smBuildRow(c: SmConnector, mode: 'explore' | 'connected'): string {
  const logoHtml = smUniquifySvgIds(c.logo, mode + '_' + c.id);
  let row = '<div class="sm-list__row" data-id="' + c.id + '" data-name="' + c.name.toLowerCase() + '">';
  row += '<span class="' + smLogoClass(c) + '">' + logoHtml + '</span>';
  row += '<div class="sm-row__meta">';
  row += '<div class="sm-row__name">' + c.name + '</div>';
  if (mode === 'explore') row += '<div class="sm-row__desc">' + c.desc + '</div>';
  row += '</div>';
  if (mode === 'explore') {
    row += '<button class="sm-row__action" data-action="connect" data-id="' + c.id + '">Connect</button>';
  } else {
    row += '<button class="sm-row__more" data-action="more" data-id="' + c.id + '" aria-label="More options for ' + c.name + '" aria-haspopup="true" aria-expanded="false">' + smMoreHorizontalIco + '</button>';
  }
  row += '</div>';
  return row;
}
