function smBuildNavItem(item: SmNavItem): string {
  const cls = item.selected ? 'sm-nav__item sm-nav__item--selected' : 'sm-nav__item';
  // data-section is used at runtime to conditionally hide items (e.g. Sources)
  const slug = item.label.toLowerCase().replace(/[^a-z0-9]+/g, '-');
  return '<div class="' + cls + '" role="button" tabindex="0" data-section="' + slug + '">'
    + '<span class="sm-nav__icon">' + item.icon + '</span>'
    + '<span>' + item.label + '</span>'
    + '</div>';
}
function smBuildNavGroup(items: SmNavItem[]): string {
  return '<div class="sm-nav__group">' + items.map(smBuildNavItem).join('') + '</div>';
}

