// Overlay keeps the frosted-glass backdrop used by the + menu and connect dialog.
css += '.sm-overlay { position: fixed; inset: 0; z-index: 300; background: rgba(255,255,255,0.7); backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); display: none; align-items: center; justify-content: center; padding: 40px; opacity: 0; transition: opacity 0.2s ease; }\n';
css += '.sm-overlay--open { display: flex; opacity: 1; }\n';
// Figma: bg white, rounded 24, drop-shadow (translated to box-shadow), px-20 py-16, gap-24.
// Inner content width = 262 (nav) + 1 (divider) + 520 (main) + 2×24 (gaps) = 831 → modal 871 wide.
// Inner content height = 700 (main) → modal 732 tall.
css += '.sm { width: 871px; height: 732px; max-height: calc(100vh - 40px); background: #ffffff; border-radius: 24px; box-shadow: 0 14px 14px rgba(0,0,0,0.24), 0 0 4px rgba(0,0,0,0.20); display: flex; flex-direction: row; align-items: flex-start; gap: 24px; padding: 16px 20px; position: relative; transform: scale(0.98); transition: transform 0.2s ease; }\n';
css += '.sm-overlay--open .sm { transform: scale(1); }\n';
// Left nav (Figma 330:17288) — w-262, flex col, gap-20 between breadcrumb and menu.
css += '.sm-nav { width: 262px; flex-shrink: 0; display: flex; flex-direction: column; gap: 20px; }\n';
