css += ".sm-nav__item { position: relative; display: flex; align-items: center; gap: 8px; padding: 14px 12px 14px 10px; border-radius: 4px; cursor: pointer; color: #242424; transition: background 0.1s; font-family: 'Segoe Sans', 'Segoe UI', system-ui, -apple-system, sans-serif; font-size: 14px; font-weight: 400; line-height: 20px; }\n";
css += '.sm-nav__item:hover { background: rgba(0,0,0,0.02); }\n';
// Selected (Figma I330:17226;6753:75836) — bg rgba(0,0,0,0.02), rounded-12, 3×16 #424242 pill at left:0.
// Selected backplate — Figma 127:128812 (bg #ebebeb) + selectedAffordance.ts contract.
css += '.sm-nav__item--selected { background: #ebebeb; border-radius: 12px; cursor: default; }\n';
css += '.sm-nav__item--selected::before { content: ""; position: absolute; left: 0; top: 50%; transform: translateY(-50%); width: 3px; height: 16px; background: #424242; border-radius: 20px; }\n';
