html += '    if (row) row.classList.add("sm-list__row--leaving");\n';
html += '    setTimeout(function(){\n';
html += '      connectedIds.delete(id);\n';
html += '      if (typeof disconnectSource === "function") { disconnectSource(id); } else { smPersist(); }\n';
html += '      if (row) row.classList.remove("sm-list__row--leaving");\n';
html += '      applyTabVisibility(); applyVisibility();\n';
html += '    }, 200);\n';
html += '  }\n';
html += '  function closeAllPops(){\n';
html += '    overlay.querySelectorAll(".sm-pop").forEach(function(p){ p.remove(); });\n';
html += '    overlay.querySelectorAll("[data-action=more][aria-expanded=true]").forEach(function(b){ b.setAttribute("aria-expanded","false"); });\n';
html += '  }\n';
html += '  function togglePop(btn){\n';
html += '    var open = btn.getAttribute("aria-expanded") === "true";\n';
html += '    closeAllPops();\n';
html += '    if (open) return;\n';
html += '    var pop = document.createElement("div");\n';
html += '    pop.className = "sm-pop";\n';
html += '    pop.innerHTML = \'<button class="sm-pop__item" type="button" data-pop-action="disconnect" data-id="\' + btn.getAttribute("data-id") + \'">Disconnect</button>\';\n';
// Append the pop as a SIBLING of the more button, not a CHILD — otherwise
// clicks on the Disconnect button bubble through the More button first, match
// the [data-action=more] selector, and re-toggle the pop (closing it) before
// the popItem branch ever runs.
html += '    btn.parentElement.appendChild(pop);\n';
html += '    btn.setAttribute("aria-expanded","true");\n';
html += '  }\n';
// Delegated clicks scoped to the overlay.
html += '  overlay.addEventListener("click", function(ev){\n';
html += '    var connectBtn = ev.target.closest("[data-action=connect]");\n';
html += '    if (connectBtn) { connect(connectBtn.getAttribute("data-id"), connectBtn); return; }\n';
html += '    var moreBtn = ev.target.closest("[data-action=more]");\n';
html += '    if (moreBtn) { ev.stopPropagation(); togglePop(moreBtn); return; }\n';
html += '    var popItem = ev.target.closest("[data-pop-action=disconnect]");\n';
html += '    if (popItem) { ev.stopPropagation(); closeAllPops(); disconnect(popItem.getAttribute("data-id")); return; }\n';
html += '    closeAllPops();\n';
html += '  });\n';
// Dismiss button (X) + backdrop click + Escape all close the overlay.
html += '  function closeOverlay(){ overlay.classList.remove("sm-overlay--open"); }\n';
html += '  overlay.querySelector("[data-action=dismiss]").addEventListener("click", closeOverlay);\n';
html += '  overlay.addEventListener("click", function(ev){ if (ev.target === overlay) closeOverlay(); });\n';
html += '  document.addEventListener("keydown", function(ev){ if (ev.key === "Escape" && overlay.classList.contains("sm-overlay--open")) closeOverlay(); });\n';
html += '  window.openCopilotSettings = function(defaultTab){\n';
// Re-read storage every open so the modal reflects any toggles/connects that
// happened in the sources menu while it was closed.
html += '    connectedIds = smReadConnected();\n';
html += '    var tab = (defaultTab === "explore" || defaultTab === "connected") ? defaultTab : (connectedIds.size > 0 ? "connected" : "explore");\n';
html += '    setActiveTab(tab);\n';
html += '    applyTabVisibility(); applyVisibility();\n';
html += '    if (input) input.value = "";\n';
html += '    overlay.classList.add("sm-overlay--open");\n';
html += '  };\n';
// Cross-surface sync: when the FCC sources menu (or another tab) writes the
// shared key, re-hydrate and re-paint. Storage events don\'t fire on the window
// that did the write, so this only catches changes from OTHER surfaces.
html += '  window.addEventListener("storage", function(e){\n';
html += '    if (e.key !== STORAGE_KEY) return;\n';
html += '    connectedIds = smReadConnected();\n';
html += '    applyTabVisibility(); applyVisibility();\n';
html += '  });\n';
html += '  applyTabVisibility(); applyVisibility();\n';
html += '})();\n';

// Wire the Copilot Menu "Chat settings" item to open the modal, and close the menu.
html += 'document.querySelectorAll(\'.cop-menu__item\').forEach(function(item) {\n';
html += '  var label = item.querySelector(".cop-menu__label");\n';
html += '  if (label && label.textContent.trim() === "Chat settings") {\n';
html += '    item.addEventListener("click", function() {\n';
html += '      _copMenu.classList.remove("cop-menu--open");\n';
html += '      _moreBtn.setAttribute("aria-expanded", "false");\n';
html += '      if (typeof window.openCopilotSettings === "function") window.openCopilotSettings();\n';
html += '    });\n';
html += '  }\n';
html += '});\n';

html += '</script>';

html += '</body>';
html += '</html>';

// ─── Write ──────────────────────────────────────────────────────────

const outDir = path.join(path.dirname(new URL(import.meta.url).pathname), '..', 'dist');
if (!fs.existsSync(outDir)) {
  fs.mkdirSync(outDir, { recursive: true });
}
const outPath = path.join(outDir, 'skillExperiment.html');
fs.writeFileSync(outPath, html, 'utf-8');
console.log('Done: ' + outPath);
